# Lợi nhuận theo giá bán p: cầu q = 100 - 2p, giá vốn 10/đơn vị
def profit(p):
    q = 100 - 2 * p
    return (p - 10) * q

def d(f, x, h=1e-6): return (f(x + h) - f(x - h)) / (2 * h)

# Gradient ascent một biến: đi theo hướng đạo hàm dương
p = 20.0
for _ in range(1000):
    p += 0.01 * d(profit, p)
print("giá tối ưu ≈", round(p, 2), " lợi nhuận ≈", round(profit(p), 2))   # p* = 30
